// Timer tracks duration for one unit of work on a Logger. Create with
// StartTimer; finish with Stop (success) or Fail.
type Timer struct {
	Logger    Logger
	Operation string
	StartedAt datetime.Time
}

// StartTimer begins timing an operation on this logger.
// Example:
//
//	t := l.StartTimer("compact")
//	...work...
//	t.Stop()
func (l Logger) StartTimer(operation string) Timer {
	return Timer{Logger: l, Operation: operation, StartedAt: datetime.Now()}
}

// Stop records a successful timer completion at Level.Info with the elapsed
// duration_ms plus operation name. Extra fields are passed as key/value pairs.
func (t *Timer) Stop(kv ...any) {
	all := []any{}
	for _, v := range kv {
		all = append(all, v)
	}
	all = append(all, "operation", t.Operation, "duration_ms", datetime.Now().Sub(t.StartedAt).Milliseconds())
	t.Logger.emit(LevelInfo, "operation complete", all)
}

// Fail records a failed timer completion at Level.Error with the elapsed
// duration_ms, operation name, and reason. Extra fields are key/value pairs.
func (t *Timer) Fail(reason string, kv ...any) {
	all := []any{}
	for _, v := range kv {
		all = append(all, v)
	}
	all = append(all, "operation", t.Operation, "duration_ms", datetime.Now().Sub(t.StartedAt).Milliseconds(), "reason", reason)
	t.Logger.emit(LevelError, "operation failed", all)
}

